ns\n\n# Common implementations:\n# 1. Simple: take the minimum value (worst case)\n# 2. Interpolated: find the exact percentile value\n\n# Let me calculate the actual 5th percentile properly and get the ES\n\nimport math\n\ndef get_percentile(data, p):\n    \"\"\"Get the p-th percentile using linear interpolation\"\"\"\n    sorted_data = sorted(data)\n    n = len(data)\n    index = (n - 1) * p  # Uses (n-1) for 0-indexed array\n    lower = int(math.floor(index))\n    upper = int(math.ceil(index))\n    frac = index - lower\n    if upper >= n:\n        return sorted_data[-1]\n    return sorted_data[lower] * (1 - frac) + sorted_data[upper] * frac\n\n# Calculate 5th percentile (VaR at 95% confidence)\nvar_95 = get_percentile(yields, 0.05)\nprint(f\"Value at Risk (5th percentile): {var_95}\")\n\n# Expected shortfall = average of all values <= VaR\nes_values = [y for y in yields if y <= var_95]\nprint(f\"Values <= 5th percentile: {es_values}\")\nes = sum(es_values) / len(es_values)\nprint(f\"Expected Shortfall (average of worst 5%): {es}\")\nprint(f\"Rounded to nearest hundredth: {round(es, 2)}\")\n\n# But wait - in the context of bond yields, what does \"shortfall\" mean?\n# If shortfall means \"below expected\" then we look at the LOW yields\n# If shortfall means \"losses\" in the sense of high yields = price loss, we look at HIGH yields\n\n# Let me also check what we get using the other interpretation\nprint(\"\\n--- If we interpret 'worst outcomes' as HIGHEST yields ---\")\nvar_95_high = get_percentile(yields, 0.95)\nprint(f\"95th percentile (high yields): {var_95_high}\")\nes_high = [y for y in yields if y >= var_95_high]\nprint(f\"Values >= 95th percentile: {es_high}\")\nes_avg_high = sum(es_high) / len(es_high)\nprint(f\"Average of top 5% yields: {es_avg_high}\")\nprint(f\"Rounded: {round(es_avg_high, 2)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
